/* E1-01/E1-02 boundary and ordering regressions; same public core, no hardware. */
#include "ann.h"
#include <stdio.h>
#include <string.h>
static unsigned checks,failures;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"line %d: %s\n",__LINE__,#x);failures++;}}while(0)
static void setup(ann_node *n,int cached){ann_out out;ann_init(n,1,100);ann_start(n,0);while(ann_next_tx(n,&out,0)){}if(cached){ann_route*r=n->routes;r->used=1;r->dst=2;r->len=2;r->path[0]=1;r->path[1]=2;r->until=10000;}}
static ann_packet response(const ann_out*out,int type){ann_packet p=out->packet;p.type=(uint8_t)type;p.path_len=2;p.path[0]=1;p.path[1]=2;p.index=0;p.ttl=8;p.payload_len=0;return p;}
static unsigned events(ann_node*n,int type){ann_event e;unsigned count=0;while(ann_next_event(n,&e))if(e.type==type)count++;return count;}
static void control_at(unsigned type,unsigned arrival,int tick_first){ann_node n;ann_out request,out;ann_packet p;uint32_t seq=0;uint8_t wire[250];int len,have;unsigned expired;setup(&n,type==ANN_ACK);CHECK(!ann_submit(&n,2,ANN_TRANSACTION,0,"x",1,100,0,0,&seq));CHECK(ann_next_tx(&n,&request,0));p=response(&request,type);len=ann_encode(&p,wire,sizeof(wire));CHECK(len>0);if(tick_first)ann_tick(&n,arrival);CHECK(!ann_receive(&n,2,wire,len,arrival));ann_tick(&n,arrival);expired=events(&n,ANN_EXPIRED);have=ann_next_tx(&n,&out,arrival);if(arrival>=100){CHECK(!n.confirmed);CHECK(expired==1);CHECK(!have);CHECK(!n.pending[0].used);CHECK(!n.routes[0].used||type==ANN_ACK);}else{CHECK(!expired);if(type==ANN_ACK){CHECK(n.confirmed==1);CHECK(!have);}else{CHECK(have&&out.packet.type==ANN_DATA);CHECK(out.packet.remaining_ms==100-arrival);len=ann_encode(&out.packet,wire,sizeof(wire));CHECK(!ann_decode(&p,wire,len));}}}
static void queued_expiry(int cached,int tick_first){ann_node n;ann_out out;uint32_t seq;setup(&n,cached);CHECK(!ann_submit(&n,2,ANN_TRANSACTION,0,"x",1,100,0,0,&seq));if(tick_first)ann_tick(&n,100);CHECK(!ann_next_tx(&n,&out,100));CHECK(events(&n,ANN_EXPIRED)==1);ann_tick(&n,101);CHECK(events(&n,ANN_EXPIRED)==0);CHECK(!n.pending[0].used);}
static void cancel_unsent(int cached){ann_node n;ann_out out;uint32_t a,b;int have;unsigned data_b=0,cancel_a=0;setup(&n,cached);CHECK(!ann_submit(&n,2,ANN_TRANSACTION,0,"a",1,1000,0,0,&a));CHECK(!ann_submit(&n,2,ANN_TRANSACTION,0,"b",1,1000,0,0,&b));CHECK(!ann_cancel(&n,a,1));while((have=ann_next_tx(&n,&out,1))){CHECK(!(out.packet.seq==a&&(out.packet.type==ANN_DATA||out.packet.type==ANN_RREQ)));if(out.packet.seq==b)data_b++;if(out.packet.type==ANN_CANCEL&&out.packet.seq==a)cancel_a++;}CHECK(data_b==1);CHECK(cancel_a==(unsigned)cached);CHECK(ann_cancel(&n,a,1)<0);CHECK(events(&n,ANN_CANCELLED)==1);}
static void cancel_wrapped(void){ann_node n;ann_out out;uint32_t seq;unsigned i;setup(&n,1);CHECK(!ann_submit(&n,2,ANN_TRANSACTION,0,"a",1,1000,0,0,&seq));out=n.out[n.out_head];n.out_head=31;n.out_count=3;n.out[31]=out;n.out[0]=out;n.out[1]=out;n.out[0].packet.type=ANN_HELLO;n.out[0].packet.seq=0;CHECK(!ann_cancel(&n,seq,0));CHECK(ann_next_tx(&n,&out,0)&&out.packet.type==ANN_HELLO);CHECK(ann_next_tx(&n,&out,0)&&out.packet.type==ANN_CANCEL);CHECK(!ann_next_tx(&n,&out,0));for(i=0;i<8;i++)CHECK(!n.pending[i].used);}
static void ack_clears_retry(void){ann_node n;ann_out data,out;ann_packet ack;uint32_t seq;uint8_t bytes[250];int len;setup(&n,1);CHECK(!ann_submit(&n,2,ANN_TRANSACTION,0,"a",1,2000,0,0,&seq));CHECK(ann_next_tx(&n,&data,0));ann_tick(&n,500);CHECK(n.out_count==1);ack=response(&data,ANN_ACK);len=ann_encode(&ack,bytes,sizeof(bytes));CHECK(!ann_receive(&n,2,bytes,len,501));CHECK(n.confirmed==1);CHECK(!ann_next_tx(&n,&out,501));}
static void cancel_after_take(void){ann_node n;ann_out sent,out;uint32_t seq;setup(&n,1);CHECK(!ann_submit(&n,2,ANN_TRANSACTION,0,"a",1,1000,0,0,&seq));CHECK(ann_next_tx(&n,&sent,0)&&sent.packet.type==ANN_DATA);CHECK(!ann_cancel(&n,seq,1));CHECK(sent.packet.type==ANN_DATA);CHECK(ann_next_tx(&n,&out,1)&&out.packet.type==ANN_CANCEL);CHECK(!ann_next_tx(&n,&out,1));}
int main(void){unsigned type,tick;for(type=ANN_RREP;type<=ANN_ACK;type++)if(type!=ANN_DATA)for(tick=0;tick<2;tick++){control_at(type,99,tick);control_at(type,100,tick);control_at(type,101,tick);}for(type=0;type<2;type++)for(tick=0;tick<2;tick++)queued_expiry(type,tick);cancel_unsent(0);cancel_unsent(1);cancel_wrapped();ack_clears_retry();cancel_after_take();printf("{\"schema\":\"ann.test.v1\",\"suite\":\"lifecycle_boundaries\",\"checks\":%u,\"failures\":%u,\"evidence_kind\":\"synthetic\"}\n",checks,failures);return failures?1:0;}
